  1→import type { TranscriptMessage, ToolCall } from "../../types"
  2→import type { TranscriptParser, TranscriptParseResult } from "./types"
  3→
  4→interface OpenCodePart {
  5→  type: string
  6→  text?: string
  7→  tool?: string
  8→  state?: {
  9→    input?: unknown
 10→    output?: string
 11→    status?: string
 12→    time?: { start?: number; end?: number }
 13→  }
 14→  time?: { start?: number; end?: number }
 15→}
 16→
 17→interface OpenCodeMessage {
 18→  info: {
 19→    role: "user" | "assistant"
 20→    time?: { created?: number; completed?: number }
 21→    id?: string
 22→  }
 23→  parts: OpenCodePart[]
 24→}
 25→
 26→interface OpenCodeLog {
 27→  info?: {
 28→    time?: {
 29→      created?: number
 30→    }
 31→  }
 32→  messages: OpenCodeMessage[]
 33→}
 34→
 35→function msToISO(ms: number | undefined, fallback: string): string {
 36→  return ms != null ? new Date(ms).toISOString() : fallback
 37→}
 38→
 39→/**
 40→ * Group and convert raw OpenCode messages into TranscriptMessages.
 41→ * Consecutive assistant messages are merged into a single turn.
 42→ */
 43→function parseOpenCodeMessages(
 44→  rawMessages: OpenCodeMessage[],
 45→  sessionCreated: string,
 46→): TranscriptMessage[] {
 47→  const result: TranscriptMessage[] = []
 48→
 49→  // Group consecutive assistant messages into a single turn
 50→  let i = 0
 51→  while (i < rawMessages.length) {
 52→    const msg = rawMessages[i]
 53→    const role = msg.info?.role
 54→
 55→    if (role === "user") {
 56→      const text = msg.parts
 57→        .filter((p) => p.type === "text")
 58→        .map((p) => p.text ?? "")
 59→        .join("\n")
 60→        .trim()
 61→
 62→      if (text) {
 63→        result.push({
 64→          id: msg.info.id ?? crypto.randomUUID(),
 65→          role: "user",
 66→          content: text,
 67→          timestamp: msToISO(msg.info.time?.created, sessionCreated),
 68→        })
 69→      }
 70→      i++
 71→    } else if (role === "assistant") {
 72→      // Collect consecutive assistant messages as one turn
 73→      const toolCalls: ToolCall[] = []
 74→      let assistantText = ""
 75→      const turnTimestamp = msToISO(msg.info.time?.created, sessionCreated)
 76→      let turnId = msg.info.id ?? crypto.randomUUID()
 77→
 78→      while (i < rawMessages.length && rawMessages[i].info?.role === "assistant") {
 79→        const assistantMsg = rawMessages[i]
 80→        const msgTs = msToISO(assistantMsg.info.time?.created, sessionCreated)
 81→
 82→        // Use the last assistant message's id if it has one
 83→        if (assistantMsg.info.id) {
 84→          turnId = assistantMsg.info.id
 85→        }
 86→
 87→        for (const part of assistantMsg.parts) {
 88→          if (part.type === "tool" && part.tool) {
 89→            const toolTs = msToISO(part.state?.time?.start, msgTs)
 90→            toolCalls.push({
 91→              id: crypto.randomUUID(),
 92→              name: part.tool,
 93→              input: (part.state?.input as Record<string, unknown>) ?? {},
 94→              timestamp: toolTs,
 95→              result: part.state?.status
 96→                ? {
 97→                    type: part.state.status === "error" ? "error" : "text",
 98→                    output: part.state.output ?? "",
 99→                    error: part.state.status === "error" ? part.state.output : undefined,
100→                  }
101→                : undefined,
102→            })
103→          } else if (part.type === "text" && part.text) {
104→            // Last text part wins as the final assistant response
105→            assistantText = part.text
106→          }
107→        }
108→        i++
109→      }
110→
111→      result.push({
112→        id: turnId,
113→        role: "assistant",
114→        content: assistantText.trim(),
115→        timestamp: turnTimestamp,
116→        toolCalls,
117→      })
118→    } else {
119→      i++
120→    }
121→  }
122→
123→  return result
124→}
125→
126→function parseOpenCodeLog(content: string): OpenCodeLog | null {
127→  try {
128→    const log: OpenCodeLog = JSON.parse(content)
129→    if (!Array.isArray(log.messages)) return null
130→    return log
131→  } catch {
132→    return null
133→  }
134→}
135→
136→/**
137→ * Parser for OpenCode session logs (single JSON with messages array).
138→ */
139→export class OpenCodeParser implements TranscriptParser {
140→  readonly name = "OpenCode"
141→  readonly format = "json" as const
142→
143→  parse(content: string): TranscriptParseResult {
144→    return this.parseFrom(content, 0)
145→  }
146→
147→  parseFrom(content: string, offset: number): TranscriptParseResult {
148→    const log = parseOpenCodeLog(content)
149→    if (!log) return { messages: [], isFallback: false }
150→
151→    const sessionCreated = msToISO(log.info?.time?.created, new Date().toISOString())
152→
153→    // Slice raw messages BEFORE grouping, matching CLI's countTranscriptItems
154→    // which counts raw messages (not grouped turns)
155→    const msgs = offset > 0 ? log.messages.slice(offset) : log.messages
156→
157→    return {
158→      messages: parseOpenCodeMessages(msgs, sessionCreated),
159→      isFallback: false,
160→    }
161→  }
162→
163→  /**
164→   * Strip an OpenCode transcript to only the fields parse() reads.
165→   * Drops: top-level metadata (slug, summary, etc.), per-message summaries
166→   * (which contain full file diffs), and per-message agent/model metadata.
167→   */
168→  strip(content: string): string {
169→    let log: Record<string, unknown>
170→    try {
171→      log = JSON.parse(content)
172→    } catch {
173→      return content
174→    }
175→
176→    const info = log.info as Record<string, unknown> | undefined
177→    const stripped: Record<string, unknown> = {
178→      // Only keep info.time.created (needed for session timestamp fallback)
179→      info: info?.time
180→        ? { time: { created: (info.time as Record<string, unknown>).created } }
181→        : undefined,
182→      messages: Array.isArray(log.messages)
183→        ? (log.messages as Array<Record<string, unknown>>).map((msg) => {
184→            const msgInfo = msg.info as Record<string, unknown> | undefined
185→            return {
186→              info: msgInfo
187→                ? { role: msgInfo.role, time: msgInfo.time, id: msgInfo.id }
188→                : undefined,
189→              parts: msg.parts,
190→            }
191→          })
192→        : [],
193→    }
194→
195→    return JSON.stringify(stripped)
196→  }
197→}
