  1→import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
  2→import { extractToolUseBlocks, stripSystemTags } from "./common"
  3→import type { TranscriptParser, TranscriptParseResult } from "./types"
  4→import { jsonlParseFrom } from "./types"
  5→
  6→// Extract text and image content from message content (string or array of blocks)
  7→interface ExtractedContent {
  8→  text: string
  9→  images: Array<{ mediaType: string; data: string }>
 10→  hasToolResults: boolean
 11→}
 12→
 13→// Pattern for image references that Claude Code outputs when it "reads" an image.
 14→// These are text markers like "[Image: source: /path/to/file.png]" - not actual image data.
 15→// We strip these since the actual images are rendered from base64 content blocks.
 16→const IMAGE_REFERENCE_PATTERN = /\[Image: source: [^\]]+\]/g
 17→
 18→function extractTextContent(content: unknown): ExtractedContent {
 19→  if (typeof content === "string") {
 20→    return {
 21→      text: content.replace(IMAGE_REFERENCE_PATTERN, "").trim(),
 22→      images: [],
 23→      hasToolResults: false,
 24→    }
 25→  }
 26→  if (!Array.isArray(content)) {
 27→    return { text: "", images: [], hasToolResults: false }
 28→  }
 29→
 30→  let text = ""
 31→  const images: Array<{ mediaType: string; data: string }> = []
 32→  let hasToolResults = false
 33→
 34→  for (const block of content) {
 35→    if (typeof block === "object" && block !== null) {
 36→      const b = block as Record<string, unknown>
 37→      if (b.type === "text") {
 38→        text += (b.text as string) || ""
 39→      } else if (b.type === "tool_result") {
 40→        hasToolResults = true
 41→      } else if (b.type === "image") {
 42→        const source = b.source as Record<string, unknown> | undefined
 43→        if (source?.type === "base64" && source.data && source.media_type) {
 44→          images.push({
 45→            mediaType: source.media_type as string,
 46→            data: source.data as string,
 47→          })
 48→        }
 49→      }
 50→    }
 51→  }
 52→  // Strip image reference markers from text (see comment above)
 53→  text = text.replace(IMAGE_REFERENCE_PATTERN, "").trim()
 54→
 55→  return { text, images, hasToolResults }
 56→}
 57→
 58→// Extract tool_result metadata from a tool result record
 59→function extractToolResultMetadata(parsed: Record<string, unknown>): ToolCallResult | undefined {
 60→  const toolUseResult = parsed.toolUseResult as Record<string, unknown> | undefined
 61→  if (!toolUseResult) return undefined
 62→
 63→  const result: ToolCallResult = {
 64→    type: (toolUseResult.type as "text" | "error") || "text",
 65→  }
 66→
 67→  // For file reads
 68→  const file = toolUseResult.file as Record<string, unknown> | undefined
 69→  if (file) {
 70→    result.file = {
 71→      filePath: file.filePath as string,
 72→      numLines: file.numLines as number | undefined,
 73→    }
 74→  }
 75→
 76→  // For errors
 77→  if (toolUseResult.error) {
 78→    result.error = toolUseResult.error as string
 79→    result.type = "error"
 80→  }
 81→
 82→  // For AskUserQuestion - extract user's answers
 83→  const answers = toolUseResult.answers as Record<string, string> | undefined
 84→  if (answers) {
 85→    result.answers = answers
 86→  }
 87→
 88→  return result
 89→}
 90→
 91→/**
 92→ * Parse Claude Code JSONL transcript into TranscriptMessage[].
 93→ * Returns a natural conversation: user prompt -> final assistant reply (before next user prompt).
 94→ * Also extracts tool calls made during each assistant turn.
 95→ */
 96→function parseClaudeCodeTranscript(jsonlContent: string): TranscriptMessage[] {
 97→  const lines = jsonlContent.split("\n").filter((line) => line.trim())
 98→
 99→  // Internal types for collecting data
100→  type InternalMessage = {
101→    role: "user" | "assistant"
102→    content: string
103→    images: Array<{ mediaType: string; data: string }>
104→    timestamp: string
105→    id: string
106→  }
107→
108→  // Collect all tool_use records: id -> { name, input, timestamp }
109→  type ToolUseData = Omit<ToolCall, "id" | "result">
110→  const toolUseById = new Map<string, ToolUseData>()
111→
112→  // Collect all tool_result records: tool_use_id -> result metadata
113→  const toolResultById = new Map<string, ToolCallResult>()
114→
115→  // First pass: collect tool_use and tool_result records
116→  for (const line of lines) {
117→    let parsed: Record<string, unknown>
118→    try {
119→      parsed = JSON.parse(line)
120→    } catch {
121→      continue
122→    }
123→
124→    const type = parsed.type as string | undefined
125→    const message = parsed.message as Record<string, unknown> | undefined
126→    const timestamp = (parsed.timestamp as string) || new Date().toISOString()
127→
128→    if (type === "assistant" && message?.content) {
129→      // Check for tool_use blocks in assistant messages
130→      const toolUses = extractToolUseBlocks(message.content)
131→      for (const tu of toolUses) {
132→        toolUseById.set(tu.id, {
133→          name: tu.name,
134→          input: tu.input,
135→          timestamp,
136→        })
137→      }
138→    } else if (type === "user" && message?.content) {
139→      // Check for tool_result blocks (they come as "user" type messages)
140→      const content = message.content as unknown[]
141→      if (Array.isArray(content)) {
142→        for (const block of content) {
143→          if (typeof block === "object" && block !== null) {
144→            const b = block as Record<string, unknown>
145→            if (b.type === "tool_result" && b.tool_use_id) {
146→              const resultMeta = extractToolResultMetadata(parsed)
147→              if (resultMeta) {
148→                toolResultById.set(b.tool_use_id as string, resultMeta)
149→              }
150→            }
151→          }
152→        }
153→      }
154→    }
155→  }
156→
157→  // Second pass: collect messages and track tool calls per turn
158→  const messages: InternalMessage[] = []
159→  const assistantByRequestId = new Map<string, number>()
160→
161→  // Track tool calls in the current turn (between user messages)
162→  // Key is the index in messages array where we'll eventually attach them
163→  const toolCallsPerTurn: ToolCall[] = []
164→
165→  for (const line of lines) {
166→    let parsed: Record<string, unknown>
167→    try {
168→      parsed = JSON.parse(line)
169→    } catch {
170→      continue
171→    }
172→
173→    const type = parsed.type as string | undefined
174→    if (type !== "user" && type !== "assistant") continue
175→
176→    const message = parsed.message as Record<string, unknown> | undefined
177→    if (!message) continue
178→
179→    const timestamp = (parsed.timestamp as string) || new Date().toISOString()
180→
181→    if (type === "assistant") {
182→      // Check for tool_use blocks first
183→      const toolUses = extractToolUseBlocks(message.content)
184→      for (const tu of toolUses) {
185→        const toolData = toolUseById.get(tu.id)
186→        if (toolData) {
187→          const toolCall: ToolCall = {
188→            id: tu.id,
189→            name: tu.name,
190→            input: tu.input,
191→            timestamp: toolData.timestamp,
192→            result: toolResultById.get(tu.id),
193→          }
194→          toolCallsPerTurn.push(toolCall)
195→        }
196→      }
197→
198→      // Also extract text content for the message
199→      const { text, images } = extractTextContent(message.content)
200→      const content = text.trim()
201→      const requestId = (parsed.requestId as string) || (message.id as string)
202→      if (!requestId) continue
203→
204→      const existingIdx = assistantByRequestId.get(requestId)
205→      if (existingIdx !== undefined) {
206→        // Streaming update: replace with latest content
207→        if (content) {
208→          messages[existingIdx].content = content
209→        }
210→        if (images.length > 0) {
211→          messages[existingIdx].images = images
212→        }
213→        // Always advance timestamp so tool calls from later streaming
214→        // lines (e.g. tool_use arriving after text) fall within the
215→        // turn's time range for getToolCallsInRange.
216→        messages[existingIdx].timestamp = timestamp
217→      } else {
218→        assistantByRequestId.set(requestId, messages.length)
219→        messages.push({
220→          role: "assistant",
221→          content,
222→          images,
223→          timestamp,
224→          id: (message.id as string) || crypto.randomUUID(),
225→        })
226→      }
227→    } else {
228→      // User message
229→      const { text, images, hasToolResults } = extractTextContent(message.content)
230→      const content = text.trim()
231→
232→      // Skip user messages that are only tool results and have no text/images
233→      if ((!content && images.length === 0) || hasToolResults) continue
234→
235→      messages.push({
236→        role: "user",
237→        content,
238→        images,
239→        timestamp,
240→        id: (parsed.uuid as string) || crypto.randomUUID(),
241→      })
242→    }
243→  }
244→
245→  // Sort by timestamp
246→  messages.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
247→
248→  // Sort tool calls by timestamp for proper ordering
249→  toolCallsPerTurn.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
250→
251→  // Build result: keep ALL assistant messages with content between user messages.
252→  // Claude Code can emit multiple assistant responses (text → tool calls → summary)
253→  // before the user responds — each is a separate API call with its own requestId.
254→  // Attach tool calls to the assistant message they follow (by timestamp range).
255→  const result: TranscriptMessage[] = []
256→  // Collect all assistants with content between user messages
257→  let pendingAssistants: InternalMessage[] = []
258→  let lastUserTimestamp: string | null = null
259→
260→  const hasContent = (m: InternalMessage) => m.content || m.images.length > 0
261→
262→  // Helper to get tool calls between two timestamps
263→  const getToolCallsInRange = (startTs: string | null, endTs: string): ToolCall[] => {
264→    const endTime = new Date(endTs).getTime()
265→    const startTime = startTs !== null ? new Date(startTs).getTime() : null
266→    return toolCallsPerTurn.filter((tc) => {
267→      const tcTime = new Date(tc.timestamp).getTime()
268→      if (startTime === null) {
269→        return tcTime <= endTime
270→      }
271→      return tcTime > startTime && tcTime <= endTime
272→    })
273→  }
274→
275→  const flushAssistants = () => {
276→    for (let i = 0; i < pendingAssistants.length; i++) {
277→      const assistant = pendingAssistants[i]
278→      // Tool calls range: from previous assistant's timestamp (or last user) to this assistant's timestamp
279→      const rangeStart = i === 0 ? lastUserTimestamp : pendingAssistants[i - 1].timestamp
280→      const turnToolCalls = getToolCallsInRange(rangeStart, assistant.timestamp)
281→      result.push({
282→        ...assistant,
283→        images: assistant.images.length > 0 ? assistant.images : undefined,
284→        toolCalls: turnToolCalls,
285→      })
286→    }
287→    pendingAssistants = []
288→  }
289→
290→  for (const msg of messages) {
291→    if (msg.role === "user") {
292→      flushAssistants()
293→      result.push({
294→        ...msg,
295→        images: msg.images.length > 0 ? msg.images : undefined,
296→      })
297→      lastUserTimestamp = msg.timestamp
298→    } else if (hasContent(msg)) {
299→      pendingAssistants.push(msg)
300→    }
301→  }
302→
303→  // Handle any remaining assistant messages after the last user message
304→  flushAssistants()
305→
306→  return result
307→}
308→
309→/** Strip system-injected tags from Claude Code message content. */
310→function stripInternalTags(content: string): string {
311→  return stripSystemTags(content).trim()
312→}
313→
314→/**
315→ * Parser for Claude Code JSONL transcripts.
316→ */
317→export class ClaudeCodeParser implements TranscriptParser {
318→  readonly name = "Claude Code"
319→  readonly format = "jsonl" as const
320→
321→  parse(jsonlContent: string): TranscriptParseResult {
322→    const messages = parseClaudeCodeTranscript(jsonlContent)
323→
324→    // Strip internal tags from all message content
325→    for (const msg of messages) {
326→      if (msg.content) {
327→        msg.content = stripInternalTags(msg.content)
328→      }
329→    }
330→
331→    return {
332→      messages,
333→      isFallback: false,
334→    }
335→  }
336→
337→  parseFrom(content: string, offset: number): TranscriptParseResult {
338→    return jsonlParseFrom(this, content, offset)
339→  }
340→}
