  1→import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
  2→import type { TranscriptParser, TranscriptParseResult } from "./types"
  3→
  4→/**
  5→ * Kiro transcript parser — handles two distinct formats:
  6→ *
  7→ * 1. **Kiro CLI** — turn-pair entries: `{ user: { content: { Prompt: ... } }, assistant: { Response: ... } }`
  8→ * 2. **Kiro IDE** — flat message entries: `{ message: { role: "user"|"assistant", content: ... } }`
  9→ *
 10→ * Both formats wrap their data in `{ history: [...] }`.
 11→ * Despite the `.jsonl` extension, the content is a single JSON object.
 12→ */
 13→
 14→interface KiroToolUse {
 15→  id: string
 16→  name: string
 17→  args: Record<string, unknown>
 18→}
 19→
 20→interface KiroToolUseResult {
 21→  tool_use_id: string
 22→  content: Array<{ Text?: string }>
 23→  status: string
 24→}
 25→
 26→interface KiroUserContent {
 27→  Prompt?: { prompt: string }
 28→  ToolUseResults?: { tool_use_results: KiroToolUseResult[] }
 29→}
 30→
 31→interface KiroAssistantContent {
 32→  ToolUse?: {
 33→    message_id: string
 34→    content: string
 35→    tool_uses: KiroToolUse[]
 36→  }
 37→  Response?: {
 38→    message_id: string
 39→    content: string
 40→  }
 41→}
 42→
 43→interface KiroCliHistoryEntry {
 44→  user: {
 45→    content: KiroUserContent
 46→    timestamp: string | null
 47→    images: Array<{ media_type: string; data: string }> | null
 48→  }
 49→  assistant: KiroAssistantContent
 50→  request_metadata?: Record<string, unknown>
 51→}
 52→
 53→interface KiroIdeHistoryEntry {
 54→  message: {
 55→    role: "user" | "assistant"
 56→    content: string | Array<{ type: string; text: string }>
 57→    id?: string
 58→  }
 59→  contextItems?: unknown[]
 60→  editorState?: unknown
 61→  promptLogs?: unknown[]
 62→  executionId?: string
 63→}
 64→
 65→type KiroHistoryEntry = KiroCliHistoryEntry | KiroIdeHistoryEntry
 66→
 67→interface KiroTranscript {
 68→  conversation_id?: string
 69→  history: KiroHistoryEntry[]
 70→}
 71→
 72→/** Detect whether a history entry is from the IDE (has `message`) or CLI (has `user`). */
 73→function isIdeEntry(entry: KiroHistoryEntry): entry is KiroIdeHistoryEntry {
 74→  return "message" in entry && entry.message != null
 75→}
 76→
 77→function parseKiroTranscript(content: string): KiroTranscript | null {
 78→  try {
 79→    const parsed = JSON.parse(content) as KiroTranscript
 80→    if (!Array.isArray(parsed.history)) return null
 81→    return parsed
 82→  } catch {
 83→    return null
 84→  }
 85→}
 86→
 87→function buildCliMessages(history: KiroCliHistoryEntry[]): TranscriptMessage[] {
 88→  // Pass 1: Collect tool results by tool_use_id
 89→  const toolResultById = new Map<string, ToolCallResult>()
 90→  for (const entry of history) {
 91→    const toolResults = entry.user.content?.ToolUseResults?.tool_use_results
 92→    if (!toolResults) continue
 93→    for (const result of toolResults) {
 94→      const textParts = result.content
 95→        .map((c) => c.Text ?? "")
 96→        .filter(Boolean)
 97→        .join("\n")
 98→      toolResultById.set(result.tool_use_id, {
 99→        type: result.status === "Success" ? "text" : "error",
100→        output: textParts || undefined,
101→        error: result.status !== "Success" ? result.status : undefined,
102→      })
103→    }
104→  }
105→
106→  // Pass 2: Build messages
107→  const messages: TranscriptMessage[] = []
108→  let lastTimestamp = new Date().toISOString()
109→
110→  for (const entry of history) {
111→    const userContent = entry.user.content
112→    const timestamp = entry.user.timestamp ?? lastTimestamp
113→    if (entry.user.timestamp) {
114→      lastTimestamp = entry.user.timestamp
115→    }
116→
117→    // Emit user message if this is a Prompt (skip ToolUseResults-only turns and null content)
118→    if (userContent?.Prompt) {
119→      const prompt = userContent.Prompt.prompt.trim()
120→      if (prompt) {
121→        messages.push({
122→          id: crypto.randomUUID(),
123→          role: "user",
124→          content: prompt,
125→          timestamp,
126→          images: entry.user.images?.map((img) => ({
127→            mediaType: img.media_type,
128→            data: img.data,
129→          })),
130→        })
131→      }
132→    }
133→
134→    // Collect tool calls from ToolUse
135→    const toolCalls: ToolCall[] = []
136→    const assistant = entry.assistant
137→
138→    if (assistant.ToolUse) {
139→      for (const tu of assistant.ToolUse.tool_uses) {
140→        toolCalls.push({
141→          id: tu.id,
142→          name: tu.name,
143→          input: tu.args,
144→          timestamp,
145→          result: toolResultById.get(tu.id),
146→        })
147→      }
148→    }
149→
150→    // Emit assistant message
151→    const assistantText = assistant.Response?.content ?? assistant.ToolUse?.content ?? ""
152→    const trimmedText = assistantText.trim()
153→
154→    // Emit if there's text or tool calls
155→    if (trimmedText || toolCalls.length > 0) {
156→      messages.push({
157→        id: assistant.Response?.message_id ?? assistant.ToolUse?.message_id ?? crypto.randomUUID(),
158→        role: "assistant",
159→        content: trimmedText,
160→        timestamp,
161→        toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
162→      })
163→    }
164→  }
165→
166→  return messages
167→}
168→
169→/** Extract plain text from Kiro IDE message content (string or content-block array). */
170→function extractIdeText(content: string | Array<{ type: string; text: string }>): string {
171→  if (typeof content === "string") return content
172→  return content
173→    .filter((block) => block.type === "text")
174→    .map((block) => block.text)
175→    .join("\n")
176→}
177→
178→/**
179→ * Build TranscriptMessages from Kiro IDE history entries.
180→ * IDE entries are flat (one entry per message, not turn-pairs).
181→ */
182→function buildIdeMessages(history: KiroIdeHistoryEntry[]): TranscriptMessage[] {
183→  const messages: TranscriptMessage[] = []
184→
185→  for (const entry of history) {
186→    const { message } = entry
187→    const text = extractIdeText(message.content).trim()
188→    if (!text) continue
189→
190→    messages.push({
191→      id: message.id ?? crypto.randomUUID(),
192→      role: message.role,
193→      content: text,
194→      timestamp: new Date().toISOString(),
195→    })
196→  }
197→
198→  return messages
199→}
200→
201→function buildMessages(history: KiroHistoryEntry[]): TranscriptMessage[] {
202→  if (history.length === 0) return []
203→
204→  // Detect format from the first entry
205→  if (isIdeEntry(history[0])) {
206→    return buildIdeMessages(history as KiroIdeHistoryEntry[])
207→  }
208→  return buildCliMessages(history as KiroCliHistoryEntry[])
209→}
210→
211→/**
212→ * Parser for Kiro session transcripts (single JSON with history array).
213→ */
214→export class KiroParser implements TranscriptParser {
215→  readonly name = "Kiro"
216→  readonly format = "json" as const
217→
218→  parse(content: string): TranscriptParseResult {
219→    const transcript = parseKiroTranscript(content)
220→    if (!transcript) return { messages: [], isFallback: false }
221→
222→    return {
223→      messages: buildMessages(transcript.history),
224→      isFallback: false,
225→    }
226→  }
227→
228→  parseFrom(content: string, offset: number): TranscriptParseResult {
229→    const transcript = parseKiroTranscript(content)
230→    if (!transcript) return { messages: [], isFallback: false }
231→
232→    const entries = offset > 0 ? transcript.history.slice(offset) : transcript.history
233→
234→    return {
235→      messages: buildMessages(entries),
236→      isFallback: false,
237→    }
238→  }
239→
240→  strip(content: string): string {
241→    let parsed: Record<string, unknown>
242→    try {
243→      parsed = JSON.parse(content)
244→    } catch {
245→      return content
246→    }
247→
248→    const history = parsed.history as KiroHistoryEntry[] | undefined
249→    if (!Array.isArray(history) || history.length === 0) {
250→      return JSON.stringify({ history: [] })
251→    }
252→
253→    // Detect format from first entry
254→    const isIde = isIdeEntry(history[0])
255→
256→    if (isIde) {
257→      const stripped: Record<string, unknown> = {
258→        history: (history as KiroIdeHistoryEntry[]).map((entry) => ({
259→          message: {
260→            role: entry.message.role,
261→            content: extractIdeText(entry.message.content),
262→            id: entry.message.id,
263→          },
264→        })),
265→      }
266→      return JSON.stringify(stripped)
267→    }
268→
269→    // CLI format: strip request_metadata, file_text from tool args, and top-level bloat
270→    const stripped: Record<string, unknown> = {
271→      conversation_id: parsed.conversation_id,
272→      history: (history as KiroCliHistoryEntry[]).map((entry) => {
273→        const { request_metadata: _, ...rest } = entry
274→
275→        // Strip file_text from tool args (can be very large)
276→        if (rest.assistant?.ToolUse?.tool_uses) {
277→          rest.assistant = {
278→            ...rest.assistant,
279→            ToolUse: {
280→              ...rest.assistant.ToolUse,
281→              tool_uses: rest.assistant.ToolUse.tool_uses.map((tu) => ({
282→                ...tu,
283→                args: { ...tu.args, file_text: undefined },
284→              })),
285→            },
286→          }
287→        }
288→
289→        return rest
290→      }),
291→    }
292→
293→    return JSON.stringify(stripped)
294→  }
295→}
