  1→import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
  2→import type { TranscriptParser, TranscriptParseResult } from "./types"
  3→
  4→/**
  5→ * Copilot CLI JSONL event structure.
  6→ * Each line is: { type, data, id, timestamp, parentId }
  7→ *
  8→ * Known event types:
  9→ * - session.start, session.model_change — session metadata
 10→ * - user.message — user prompts
 11→ * - assistant.turn_start, assistant.message, assistant.turn_end — assistant turns
 12→ * - tool.execution_start, tool.execution_complete — tool lifecycle
 13→ */
 14→interface CopilotEvent {
 15→  type: string
 16→  data: Record<string, unknown>
 17→  id: string
 18→  timestamp: string
 19→  parentId: string | null
 20→}
 21→
 22→/**
 23→ * Tool request as it appears in assistant.message data.toolRequests[].
 24→ * Field names match the real Copilot CLI JSONL format.
 25→ */
 26→interface CopilotToolRequest {
 27→  toolCallId?: string
 28→  name?: string
 29→  arguments?: Record<string, unknown>
 30→}
 31→
 32→/**
 33→ * Parse a Copilot CLI JSONL transcript into TranscriptMessage[].
 34→ *
 35→ * Copilot CLI format: each line is a JSON object with:
 36→ * - type: "session.start" | "user.message" | "assistant.turn_start" | "assistant.message" | "assistant.turn_end"
 37→ * - data: event-specific payload
 38→ * - id: UUID
 39→ * - timestamp: ISO 8601
 40→ * - parentId: UUID or null
 41→ *
 42→ * user.message → data.content (string)
 43→ * assistant.message → data.content (string), data.toolRequests (array), data.reasoningText (string)
 44→ * assistant.turn_start / assistant.turn_end → turn boundaries (used for grouping)
 45→ */
 46→function parseCopilotCliTranscript(jsonlContent: string): TranscriptMessage[] {
 47→  const lines = jsonlContent
 48→    .split("\n")
 49→    .map((line) => line.trim())
 50→    .filter(Boolean)
 51→
 52→  const result: TranscriptMessage[] = []
 53→
 54→  // Track current turn's assistant content and tool calls
 55→  let pendingAssistantParts: string[] = []
 56→  let pendingToolCalls: ToolCall[] = []
 57→  let pendingTimestamp: string | null = null
 58→  let pendingId: string | null = null
 59→
 60→  const flushAssistant = () => {
 61→    if (pendingAssistantParts.length === 0 && pendingToolCalls.length === 0) {
 62→      pendingTimestamp = null
 63→      pendingId = null
 64→      return
 65→    }
 66→    const content = pendingAssistantParts.join("\n\n").trim()
 67→    if (content || pendingToolCalls.length > 0) {
 68→      result.push({
 69→        id: pendingId ?? crypto.randomUUID(),
 70→        role: "assistant",
 71→        content,
 72→        timestamp: pendingTimestamp ?? new Date().toISOString(),
 73→        toolCalls: pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
 74→      })
 75→    }
 76→    pendingAssistantParts = []
 77→    pendingToolCalls = []
 78→    pendingTimestamp = null
 79→    pendingId = null
 80→  }
 81→
 82→  for (const line of lines) {
 83→    let event: CopilotEvent
 84→    try {
 85→      event = JSON.parse(line)
 86→    } catch {
 87→      continue
 88→    }
 89→
 90→    if (!event.type || !event.data) continue
 91→
 92→    switch (event.type) {
 93→      case "user.message": {
 94→        // Flush any pending assistant content before a new user message
 95→        flushAssistant()
 96→
 97→        const content = typeof event.data.content === "string" ? event.data.content.trim() : ""
 98→        if (content) {
 99→          result.push({
100→            id: event.id ?? crypto.randomUUID(),
101→            role: "user",
102→            content,
103→            timestamp: event.timestamp ?? new Date().toISOString(),
104→          })
105→        }
106→        break
107→      }
108→
109→      case "assistant.message": {
110→        const content = typeof event.data.content === "string" ? event.data.content.trim() : ""
111→        if (content) {
112→          pendingAssistantParts.push(content)
113→        }
114→
115→        // Set timestamp from first assistant.message in this turn
116→        if (!pendingTimestamp) {
117→          pendingTimestamp = event.timestamp ?? new Date().toISOString()
118→        }
119→        if (!pendingId) {
120→          pendingId = event.id
121→        }
122→
123→        // Extract tool requests
124→        const toolRequests = event.data.toolRequests as CopilotToolRequest[] | undefined
125→        if (Array.isArray(toolRequests)) {
126→          for (const tr of toolRequests) {
127→            if (tr.name) {
128→              pendingToolCalls.push({
129→                id: tr.toolCallId ?? crypto.randomUUID(),
130→                name: tr.name,
131→                input: tr.arguments ?? {},
132→                timestamp: event.timestamp ?? new Date().toISOString(),
133→              })
134→            }
135→          }
136→        }
137→        break
138→      }
139→
140→      case "tool.execution_complete": {
141→        // Match tool result back to pending tool call by toolCallId
142→        const toolCallId = event.data.toolCallId as string | undefined
143→        if (toolCallId) {
144→          const matchingCall = pendingToolCalls.find((tc) => tc.id === toolCallId)
145→          if (matchingCall) {
146→            const success = event.data.success as boolean | undefined
147→            const error = event.data.error as { message?: string } | undefined
148→            const resultData = event.data.result as { content?: string } | undefined
149→
150→            const toolResult: ToolCallResult = {
151→              type: success === false ? "error" : "text",
152→            }
153→            if (error?.message) {
154→              toolResult.error = error.message
155→            }
156→            if (resultData?.content) {
157→              toolResult.output = resultData.content
158→            }
159→            matchingCall.result = toolResult
160→          }
161→        }
162→        break
163→      }
164→
165→      case "assistant.turn_end": {
166→        // Flush assistant content at end of turn
167→        flushAssistant()
168→        break
169→      }
170→
171→      // session.start, session.model_change, assistant.turn_start,
172→      // tool.execution_start are metadata — skip
173→      default:
174→        break
175→    }
176→  }
177→
178→  // Flush any remaining assistant content (in case no turn_end at EOF)
179→  flushAssistant()
180→
181→  return result
182→}
183→
