 1→// Session management using KV storage
 2→
 3→import type { Session } from "../types"
 4→
 5→const SESSION_TTL = 60 * 60 * 24 * 7 // 7 days in seconds
 6→
 7→// Create a new session
 8→export async function createSession(kv: KVNamespace, userId: string): Promise<string> {
 9→  const token = crypto.randomUUID()
10→
11→  const session: Session = {
12→    userId,
13→    expiresAt: Date.now() + SESSION_TTL * 1000,
14→  }
15→
16→  await kv.put(`session:${token}`, JSON.stringify(session), {
17→    expirationTtl: SESSION_TTL,
18→  })
19→
20→  return token
21→}
22→
23→// Get session by token
24→export async function getSession(kv: KVNamespace, token: string): Promise<Session | null> {
25→  const data = await kv.get<Session>(`session:${token}`, "json")
26→
27→  if (!data) {
28→    return null
29→  }
30→
31→  // Check if expired (belt and suspenders with KV TTL)
32→  if (Date.now() > data.expiresAt) {
33→    await kv.delete(`session:${token}`)
34→    return null
35→  }
36→
37→  return data
38→}
39→
40→// Delete session (logout)
41→export async function deleteSession(kv: KVNamespace, token: string): Promise<void> {
42→  await kv.delete(`session:${token}`)
43→}
44→
45→// Extend session (refresh)
46→export async function extendSession(kv: KVNamespace, token: string): Promise<void> {
47→  const session = await getSession(kv, token)
48→
49→  if (session) {
50→    session.expiresAt = Date.now() + SESSION_TTL * 1000
51→    await kv.put(`session:${token}`, JSON.stringify(session), {
52→      expirationTtl: SESSION_TTL,
53→    })
54→  }
55→}
