import { describe, it, expect } from "vitest"

import { UnifiedTranscriptParser, isUnifiedTranscript } from "./unified-transcript-parser"

function jsonl(...lines: Record<string, unknown>[]): string {
  return lines.map((l) => JSON.stringify(l)).join("\n")
}

function userLine(text: string, ts: string, id = "prt_" + ts) {
  return {
    v: 1,
    agent: "opencode",
    cli_version: "0.5.1",
    type: "user",
    ts,
    content: [{ id, text }],
  }
}

function assistantLine(
  content: Record<string, unknown>[],
  ts: string,
  id = "msg_" + ts,
) {
  return {
    v: 1,
    agent: "opencode",
    cli_version: "0.5.1",
    type: "assistant",
    ts,
    id,
    content,
  }
}

function textItem(text: string) {
  return { text, type: "text" }
}

function toolUseItem(
  name: string,
  input: Record<string, unknown>,
  result: { output: string; status: string },
  id = "toolu_" + name,
) {
  return { id, input, name, type: "tool_use", result }
}

const parser = new UnifiedTranscriptParser()

describe("UnifiedTranscriptParser", () => {
  it("parses empty input", () => {
    const result = parser.parse("")
    expect(result.messages).toEqual([])
    expect(result.isFallback).toBe(false)
  })

  it("parses a simple user-assistant exchange", () => {
    const input = jsonl(
      userLine("hello", "2026-03-18T20:58:45.015Z"),
      assistantLine([textItem("hi there")], "2026-03-18T20:58:45.023Z"),
    )
    const result = parser.parse(input)
    expect(result.messages).toHaveLength(2)
    expect(result.messages[0]).toMatchObject({
      role: "user",
      content: "hello",
      timestamp: "2026-03-18T20:58:45.015Z",
    })
    expect(result.messages[1]).toMatchObject({
      role: "assistant",
      content: "hi there",
      timestamp: "2026-03-18T20:58:45.023Z",
    })
  })

  it("uses content[0].id as the user message id", () => {
    const input = jsonl(userLine("hello", "2026-01-01T00:00:00Z", "prt_abc123"))
    const result = parser.parse(input)
    expect(result.messages[0].id).toBe("prt_abc123")
  })

  it("uses line id as the assistant message id", () => {
    const input = jsonl(
      assistantLine([textItem("ok")], "2026-01-01T00:00:00Z", "msg_xyz789"),
    )
    const result = parser.parse(input)
    expect(result.messages[0].id).toBe("msg_xyz789")
  })

  it("parses assistant message with text and a tool call", () => {
    const input = jsonl(
      assistantLine(
        [
          textItem("Let me explore the codebase."),
          toolUseItem("task", { prompt: "search" }, { output: "found it", status: "done" }),
        ],
        "2026-03-18T20:58:45.023Z",
        "msg_001",
      ),
    )
    const result = parser.parse(input)
    expect(result.messages).toHaveLength(1)

    const msg = result.messages[0]
    expect(msg.content).toBe("Let me explore the codebase.")
    expect(msg.toolCalls).toHaveLength(1)
    expect(msg.toolCalls![0]).toMatchObject({
      id: "toolu_task",
      name: "task",
      input: { prompt: "search" },
      timestamp: "2026-03-18T20:58:45.023Z",
      result: { type: "text", output: "found it" },
    })
  })

  it("parses assistant message with multiple tool calls", () => {
    const input = jsonl(
      assistantLine(
        [
          textItem("Reading files:"),
          toolUseItem("read", { filePath: "/a.go" }, { output: "content a", status: "done" }, "toolu_1"),
          toolUseItem("read", { filePath: "/b.go" }, { output: "content b", status: "done" }, "toolu_2"),
          toolUseItem("read", { filePath: "/c.go" }, { output: "content c", status: "done" }, "toolu_3"),
        ],
        "2026-03-18T21:00:50.948Z",
        "msg_002",
      ),
    )
    const result = parser.parse(input)
    expect(result.messages).toHaveLength(1)
    expect(result.messages[0].toolCalls).toHaveLength(3)
    expect(result.messages[0].toolCalls!.map((t) => t.id)).toEqual(["toolu_1", "toolu_2", "toolu_3"])
  })

  it("parses assistant message with tool call only (no text)", () => {
    const input = jsonl(
      assistantLine(
        [toolUseItem("bash", { command: "go test ./..." }, { output: "PASS", status: "done" })],
        "2026-03-18T21:02:10.613Z",
        "msg_003",
      ),
    )
    const result = parser.parse(input)
    expect(result.messages).toHaveLength(1)
    expect(result.messages[0].content).toBe("")
    expect(result.messages[0].toolCalls).toHaveLength(1)
    expect(result.messages[0].toolCalls![0].name).toBe("bash")
  })

  it("skips assistant message with empty text and no tool calls", () => {
    const input = jsonl(
      assistantLine([textItem("")], "2026-03-18T21:02:22.124Z", "msg_004"),
    )
    const result = parser.parse(input)
    // Empty text assistant message still produces a message (content is empty string)
    expect(result.messages).toHaveLength(1)
    expect(result.messages[0].content).toBe("")
  })

  it("does not merge consecutive assistant lines", () => {
    const input = jsonl(
      assistantLine([textItem("first")], "2026-03-18T21:00:00Z", "msg_a"),
      assistantLine([textItem("second")], "2026-03-18T21:00:01Z", "msg_b"),
      assistantLine([textItem("third")], "2026-03-18T21:00:02Z", "msg_c"),
    )
    const result = parser.parse(input)
    expect(result.messages).toHaveLength(3)
    expect(result.messages[0].id).toBe("msg_a")
    expect(result.messages[1].id).toBe("msg_b")
    expect(result.messages[2].id).toBe("msg_c")
  })

  it("handles user content items without a type field", () => {
    const input = jsonl({
      v: 1,
      agent: "opencode",
      type: "user",
      ts: "2026-03-18T20:58:45.015Z",
      content: [{ id: "prt_abc", text: "no type field here" }],
    })
    const result = parser.parse(input)
    expect(result.messages).toHaveLength(1)
    expect(result.messages[0].content).toBe("no type field here")
  })

  it("maps error tool results correctly", () => {
    const input = jsonl(
      assistantLine(
        [
          toolUseItem(
            "bash",
            { command: "fail" },
            { output: "command not found", status: "error" },
          ),
        ],
        "2026-01-01T00:00:00Z",
      ),
    )
    const result = parser.parse(input)
    const toolCall = result.messages[0].toolCalls![0]
    expect(toolCall.result).toMatchObject({
      type: "error",
      output: "command not found",
      error: "command not found",
    })
  })

  describe("parseFrom", () => {
    const input = jsonl(
      userLine("first", "2026-01-01T00:00:00Z"),
      assistantLine([textItem("response 1")], "2026-01-01T00:00:01Z", "msg_1"),
      userLine("second", "2026-01-01T00:00:02Z"),
      assistantLine([textItem("response 2")], "2026-01-01T00:00:03Z", "msg_2"),
    )

    it("returns all messages when offset is 0", () => {
      const result = parser.parseFrom(input, 0)
      expect(result.messages).toHaveLength(4)
    })

    it("skips lines before the offset", () => {
      const result = parser.parseFrom(input, 2)
      expect(result.messages).toHaveLength(2)
      expect(result.messages[0]).toMatchObject({ role: "user", content: "second" })
      expect(result.messages[1]).toMatchObject({ role: "assistant", content: "response 2" })
    })

    it("returns empty when offset exceeds line count", () => {
      const result = parser.parseFrom(input, 100)
      expect(result.messages).toEqual([])
    })
  })

  describe("strip", () => {
    it("removes v, agent, and cli_version fields", () => {
      const input = jsonl(
        userLine("hello", "2026-01-01T00:00:00Z", "prt_1"),
        assistantLine([textItem("hi")], "2026-01-01T00:00:01Z", "msg_1"),
      )
      const stripped = parser.strip(input)
      const lines = stripped.split("\n").map((l) => JSON.parse(l))

      for (const line of lines) {
        expect(line).not.toHaveProperty("v")
        expect(line).not.toHaveProperty("agent")
        expect(line).not.toHaveProperty("cli_version")
      }

      expect(lines[0]).toMatchObject({ type: "user", ts: "2026-01-01T00:00:00Z" })
      expect(lines[1]).toMatchObject({ type: "assistant", ts: "2026-01-01T00:00:01Z", id: "msg_1" })
    })

    it("returns content as-is for non-JSONL input", () => {
      const garbage = "not valid jsonl"
      expect(parser.strip(garbage)).toBe(garbage)
    })
  })
})

describe("isUnifiedTranscript", () => {
  it("returns true for valid unified transcript content", () => {
    const input = jsonl(userLine("hello", "2026-01-01T00:00:00Z"))
    expect(isUnifiedTranscript(input)).toBe(true)
  })

  it("returns true for assistant-first content", () => {
    const input = jsonl(assistantLine([textItem("hi")], "2026-01-01T00:00:00Z"))
    expect(isUnifiedTranscript(input)).toBe(true)
  })

  it("returns false for OpenCode JSON export format", () => {
    const input = JSON.stringify({
      info: { time: { created: 1234567890 } },
      messages: [{ info: { role: "user" }, parts: [{ type: "text", text: "hi" }] }],
    })
    expect(isUnifiedTranscript(input)).toBe(false)
  })

  it("returns false for Claude Code JSONL format", () => {
    const input = JSON.stringify({
      type: "user",
      message: { content: "hello" },
      timestamp: "2026-01-01T00:00:00Z",
      uuid: "u-1",
    })
    expect(isUnifiedTranscript(input)).toBe(false)
  })

  it("returns false for empty string", () => {
    expect(isUnifiedTranscript("")).toBe(false)
  })

  it("returns false for invalid JSON", () => {
    expect(isUnifiedTranscript("{broken")).toBe(false)
  })
})

import { describe, expect, it } from "vitest"

import { CodexParser } from "./codex-parser"

const rolloutTranscript = [
  JSON.stringify({
    timestamp: "2026-03-25T11:31:11.752Z",
    type: "session_meta",
    payload: { id: "019d24c3", timestamp: "2026-03-25T11:31:10.922Z" },
  }),
  JSON.stringify({
    timestamp: "2026-03-25T11:31:11.754Z",
    type: "response_item",
    payload: {
      type: "message",
      role: "user",
      content: [{ type: "input_text", text: "Create a file called hello.txt" }],
    },
  }),
  JSON.stringify({
    timestamp: "2026-03-25T11:31:13.000Z",
    type: "response_item",
    payload: {
      type: "message",
      id: "assistant-1",
      role: "assistant",
      content: [{ type: "output_text", text: "Creating the file now." }],
    },
  }),
  JSON.stringify({
    timestamp: "2026-03-25T11:31:14.000Z",
    type: "response_item",
    payload: {
      type: "custom_tool_call",
      status: "completed",
      call_id: "call_1",
      name: "apply_patch",
      input: "*** Begin Patch\n*** Add File: hello.txt\n+Hello World\n*** End Patch\n",
    },
  }),
  JSON.stringify({
    timestamp: "2026-03-25T11:31:14.500Z",
    type: "response_item",
    payload: {
      type: "custom_tool_call_output",
      call_id: "call_1",
      output: { type: "text", text: "Success. Updated: A hello.txt" },
    },
  }),
].join("\n")

describe("CodexParser", () => {
  it("parses legacy rollout transcripts into user and assistant turns", () => {
    const parser = new CodexParser()
    const result = parser.parse(rolloutTranscript)

    expect(result.isFallback).toBe(false)
    expect(result.messages).toHaveLength(2)
    expect(result.messages[0]).toMatchObject({
      role: "user",
      content: "Create a file called hello.txt",
    })
    expect(result.messages[1]).toMatchObject({
      id: "assistant-1",
      role: "assistant",
      content: "Creating the file now.",
    })
    expect(result.messages[1].toolCalls).toEqual([
      {
        id: "call_1",
        name: "apply_patch",
        input: {
          patch: "*** Begin Patch\n*** Add File: hello.txt\n+Hello World\n*** End Patch\n",
        },
        timestamp: "2026-03-25T11:31:14.000Z",
        result: {
          type: "text",
          output: "Success. Updated: A hello.txt",
        },
      },
    ])
  })

  it("supports line-based offsets for legacy rollout transcripts", () => {
    const parser = new CodexParser()
    const result = parser.parseFrom(rolloutTranscript, 2)

    expect(result.messages).toHaveLength(1)
    expect(result.messages[0].role).toBe("assistant")
    expect(result.messages[0].toolCalls).toHaveLength(1)
  })

  it("delegates unified transcript.jsonl content to the shared parser", () => {
    const parser = new CodexParser()
    const unifiedTranscript = [
      JSON.stringify({
        v: 1,
        type: "user",
        ts: "2026-03-26T10:00:00Z",
        content: [{ text: "Fix the failing test" }],
      }),
      JSON.stringify({
        v: 1,
        type: "assistant",
        id: "assistant-unified",
        ts: "2026-03-26T10:01:00Z",
        content: [
          { type: "text", text: "I fixed it." },
          {
            type: "tool_use",
            id: "tool-1",
            name: "apply_patch",
            input: { patch: "*** Begin Patch\n*** Update File: test.ts\n*** End Patch\n" },
            result: { status: "success", output: "patched" },
          },
