    const result = parser.parse(unifiedTranscript)

    expect(result.isFallback).toBe(false)
    expect(result.messages).toHaveLength(2)
    expect(result.messages[1]).toMatchObject({
      id: "assistant-unified",
      role: "assistant",
      content: "I fixed it.",
    })
    expect(result.messages[1].toolCalls).toEqual([
      {
        id: "tool-1",
        name: "apply_patch",
        input: { patch: "*** Begin Patch\n*** Update File: test.ts\n*** End Patch\n" },
        timestamp: "2026-03-26T10:01:00Z",
        result: {
          type: "text",
          output: "patched",
          error: undefined,
        },
      },
    ])
  })

  it("preserves args and text payload fields through strip", () => {
    const parser = new CodexParser()
    const transcript = [
      JSON.stringify({
        timestamp: "2026-03-26T10:00:00Z",
        type: "response_item",
        payload: {
          type: "message",
          role: "user",
          content: [{ type: "input_text", text: "Run two tools" }],
        },
      }),
      JSON.stringify({
        timestamp: "2026-03-26T10:00:01Z",
        type: "response_item",
        payload: {
          type: "function_call",
          call_id: "call-args",
          name: "search",
          args: "needle",
        },
      }),
      JSON.stringify({
        timestamp: "2026-03-26T10:00:02Z",
        type: "response_item",
        payload: {
          type: "local_shell_call",
          call_id: "call-text",
          text: "echo hello",
        },
      }),
    ].join("\n")

    const stripped = parser.strip(transcript)
    const result = parser.parse(stripped)

    expect(result.messages).toHaveLength(2)
    expect(result.messages[1].toolCalls).toEqual([
      {
        id: "call-args",
        name: "search",
        input: { input: "needle" },
        timestamp: "2026-03-26T10:00:01Z",
      },
      {
        id: "call-text",
        name: "shell",
        input: { command: "echo hello" },
        timestamp: "2026-03-26T10:00:02Z",
      },
    ])
  })
})

