  created_at: string
  repos_synced_at: string | null
  last_visited_at: string | null
}

export interface RefreshState {
  user_id: string
  last_refreshed_at: string | null
  next_refresh_at: string | null
}

// Session types

export interface Session {
  userId: string
  expiresAt: number
}

// API response types

export interface GitHubUser {
  id: number
  login: string
  name: string | null
  avatar_url: string
  email: string | null
}

// Cache types

export interface CachedUser {
  id: string
  github_id: number
  github_login: string | null
  github_token_enc: string | null
  github_refresh_token_enc: string | null
  github_token_expires_at: string | null
  repos_synced_at: string | null
  cached_at: string
}

export interface CachedFollowers {
  followers: Array<{
    login: string
    avatar_url: string
    html_url: string
  }>
  following: Array<{
    login: string
    avatar_url: string
    html_url: string
  }>
  updated_at: string
}

export interface CachedStarred {
  starred: Array<{
    name: string
    full_name: string
    description: string | null
    html_url: string
    stargazers_count: number
    language: string | null
  }>
  updated_at: string
}

export interface CachedWatched {
  watched: Array<{
    name: string
    full_name: string
    description: string | null
    html_url: string
  }>
  updated_at: string
}

export interface CachedRepos {
  repos: Array<{
    name: string
    full_name: string
    description: string | null
    html_url: string
    stargazers_count: number
    language: string | null
    private: boolean
    updated_at: string
  }>
  updated_at: string
}

export interface CachedContributions {
  total_count: number
  contributions: Array<{
    date: string
    count: number
  }>
  updated_at: string
}

export interface CachedPRs {
  prs: Array<{
    id: number
    number: number
    title: string
    html_url: string
    state: string
    repo_full_name: string
    created_at: string
    updated_at: string
    draft: boolean
    merged_at: string | null
  }>
  updated_at: string
}

export interface RepoCommitActivity {
  repo_full_name: string
  // Weekly totals for the last 52 weeks (oldest to newest)
  weeks: number[]
  // Unix timestamp of the first week (for week rollover calculation)
  week_start?: number
}

export interface CachedCommitActivity {
  activity: RepoCommitActivity[]
  updated_at: string
}

export interface CommitInfo {
  sha: string
  message: string
  author: string
  authorUsername: string | null
  authorId: number | null
  date: string
  url: string
}

export interface CachedRepoCommits {
  commits: RepoCommitListItem[]
  repo_full_name: string
  updated_at: string
  app_has_access?: boolean | null
  session_branch_exists?: boolean | null
  history_status?: "pending" | "syncing" | "complete" | "error" | null
  history_syncing?: boolean
  history_complete?: boolean
  history_pages_fetched?: number
}

export interface RepoCommitListItem {
  commitSha: string
  commitMessage: string | null
  commitAuthor: string | null
  commitAuthorUsername: string | null
  commitDate: string | null
  additions: number | null
  deletions: number | null
  filesChanged: number | null
  filesTouched: string[] | null
  fileStats: FileStats[] | null
  url: string | null
  checkpoints: CheckpointInfo[]
}

export interface SessionInfo {
  prompt: string | null
  agent: string
  steps: number
  // V1 fields
  sessionId?: string
  createdAt?: string
  isTask?: boolean
  toolUseId?: string
  transcriptIdentifierAtStart?: string
  checkpointTranscriptStart?: number
  summary?: SessionSummary
  // Per-session token usage
  tokenUsage?: {
    inputTokens: number
    cacheCreationTokens: number
    cacheReadTokens: number
    outputTokens: number
    apiCallCount: number
  }
  // Per-session attribution
  attribution?: {
    calculatedAt: string
    agentLines: number
    humanAdded: number
    humanModified: number
    humanRemoved: number
    totalCommitted: number
    agentPercentage: number
  }
}

// V1 format types for parsing checkpoint data

/** V1 root metadata (CheckpointSummary) - stored at checkpoint root */
export interface CheckpointSummary {
  checkpoint_id: string
  strategy: string
  branch?: string
  checkpoints_count: number
  files_touched: string[]
  sessions: SessionFilePaths[]
  token_usage?: TokenUsage
  /** Aggregated attribution across all sessions in this checkpoint. Present only for multi-session checkpoints. Prefer this over per-session attribution when available. */
  combined_attribution?: InitialAttribution
}

/** Paths to session files within a checkpoint folder */
export interface SessionFilePaths {
  metadata: string
  transcript: string
  content_hash: string
  prompt: string
}

/** Aggregated token usage metrics */
export interface TokenUsage {
  input_tokens: number
  cache_creation_tokens: number
  cache_read_tokens: number
  output_tokens: number
  api_call_count: number
}

/** V1 session metadata (CommittedMetadata) - stored per-session */
export interface CommittedMetadata {
  checkpoint_id: string
  session_id: string
  strategy: string
  created_at: string
  branch?: string
  checkpoints_count: number
  files_touched: string[]
  agent: string
  is_task?: boolean
  tool_use_id?: string
  transcript_identifier_at_start?: string
  /** @deprecated Use checkpoint_transcript_start instead */
  transcript_lines_at_start?: number
  checkpoint_transcript_start?: number
  token_usage?: TokenUsage
  summary?: SessionSummary
  initial_attribution?: InitialAttribution
}

/** Session summary from AI analysis */
export interface SessionSummary {
  intent: string
  outcome: string
  learnings: {
    repo: string[]
    code: Array<{ path: string; line: number; finding: string }>
    workflow: string[]
  }
  friction: string[]
  open_items: string[]
}

/** Attribution metrics calculated at checkpoint time */
export interface InitialAttribution {
  calculated_at: string
  agent_lines: number
  human_added: number
  human_modified: number
  human_removed: number
  total_committed: number
  agent_percentage: number
}

// Per-file stats for a commit
export interface FileStats {
  filename: string
  status: "added" | "removed" | "modified" | "renamed" | "copied" | "changed" | "unchanged"
  additions: number
  deletions: number
  patch?: string | null // Unified diff for this file
  patchTruncated?: boolean // True if patch was truncated due to size limits
}

export interface CheckpointInfo {
  // The commit on the branch (may be null if branch push webhook hasn't arrived yet)
  commitSha: string | null
  commitMessage: string | null
  commitAuthor: string | null
  commitAuthorUsername: string | null
  commitDate: string | null
  // Diff stats from commit (may be null)
  additions: number | null
  deletions: number | null
  filesChanged: number | null
  filesTouched: string[] | null
  // Per-file stats with additions/deletions breakdown
  fileStats: FileStats[] | null
  // The checkpoint ID from Entire-Checkpoint trailer (maps to folder in session branch)
  checkpointId: string
  // Created at timestamp (from metadata.json, used for sorting when no commit date)
  createdAt: string
  // Sessions associated with this checkpoint
  sessions: SessionInfo[]
  // Number of sessions associated with this checkpoint
  sessionCount: number
  // Total steps across all sessions
  totalSteps: number
  // Unique agents involved in this checkpoint
  agents: string[]
  // Token usage (may be null if not tracked)
  inputTokens: number | null
  cacheCreationTokens: number | null
  cacheReadTokens: number | null
  outputTokens: number | null
  apiCallCount: number | null
  // Attribution metrics (may be null if not calculated)
  attribution: {
    calculatedAt: string
    agentLines: number
    humanAdded: number
    humanModified: number
    humanRemoved: number
    totalCommitted: number
    agentPercentage: number
  } | null
  // Repo where checkpoint data lives (differs from source repo for checkpoint_remote configs)
  checkpointRepoFullName: string | null
}

// Transcript types for session conversations
export interface TranscriptImage {
  mediaType: string
  data: string // base64 encoded
}

// Tool call result metadata (not full content - that would be too large)
export interface ToolCallResult {
  type: "text" | "error"
  // For Read tool
  file?: {
    filePath: string
    numLines?: number
  }
  // For Grep tool
  matchCount?: number
  // For Bash tool (truncated output)
  output?: string
  // Error message if tool failed
  error?: string
  // For AskUserQuestion tool - the user's answers
  answers?: Record<string, string>
}

// Raw tool_use block extracted from message content
export interface ToolUseBlock {
  id: string
  name: string
  input: Record<string, unknown>
}

// Tool call made by the agent during a turn
export interface ToolCall extends ToolUseBlock {
  timestamp: string
  result?: ToolCallResult
}

export interface TranscriptMessage {
  id: string
  role: "user" | "assistant"
  content: string
  images?: TranscriptImage[]
  timestamp: string
  toolCalls?: ToolCall[] // Tools used during this assistant turn
}

// Per-session line-level attribution
export interface SessionAttribution {
  calculatedAt: string
  agentLines: number
  humanAdded: number
  humanModified: number
  humanRemoved: number
  totalCommitted: number
  agentPercentage: number
}

export interface SessionTranscript {
  sessionId: string
  agent: string
  messages: TranscriptMessage[]
  // Transcript state at session start - used to show only relevant messages
  transcriptIdentifierAtStart: string | null
  // Per-session token usage (from child metadata.json)
  tokenUsage?: {
    inputTokens: number
    outputTokens: number
  }
  // Per-session line-level attribution (from child metadata.json)
  attribution?: SessionAttribution
  // Parse quality indicators
  /** True when a native parser was not available for this agent */
  parsingFallback?: boolean
  /** Warning message when transcript parsing may be incomplete */
  parsingWarning?: string
}

export interface CheckpointTranscriptResponse {
  checkpointId: string
  sessions: SessionTranscript[]
}

// Cached transcript type
export interface CachedTranscript {
  checkpointId: string
  sessions: SessionTranscript[]
  cached_at: string
}

// ============================================================================
// Trail types
// ============================================================================

/** Trail status enum - lifecycle stages of a trail */
export type TrailStatus = "draft" | "open" | "in_progress" | "in_review" | "merged" | "closed"

export type TrailPriority = "urgent" | "high" | "medium" | "low" | "none"
export type TrailType = "bug" | "feature" | "chore" | "docs" | "refactor"

export interface TrailReviewer {
  login: string
  status: "pending" | "approved" | "changes_requested"
}

/** A single review event stored natively in reviews.json */
export interface TrailReview {
  id: string
  author: string
  event: "approved" | "changes_requested"
  body: string | null
  /** HEAD SHA of the trail branch at the time the review was submitted */
  commit_sha: string
  created_at: string
}

/** Reviews file format for trails */
export interface TrailReviews {
  reviews: TrailReview[]
}

/** Merge-readiness assessment for a trail */
export interface TrailMergeability {
  /** Whether all reviewers have approved */
  reviews_approved: boolean
  /** Whether CI checks have passed on the latest commit */
  checks_passed: boolean
  /** Overall check status */
  checks_status: "success" | "failure" | "pending" | "none"
  /** Individual check details */
  checks: Array<{ name: string; status: string; conclusion: string | null }>
  /** Whether the branch has diverged from base (potential conflicts) */
  has_conflicts: boolean
  /** Number of commits the trail branch is behind the base branch */
  behind_by: number
  /** Whether all merge-readiness conditions are met */
  mergeable: boolean
}

/** Trail metadata stored in entire/trails/v1 branch */
export interface TrailMetadata {
  trail_id: string
  branch: string
  base: string
  title: string
  body: string
  status: TrailStatus
  author: string
  assignees: string[]
  labels: string[]
  created_at: string
  updated_at: string
  merged_at: string | null
  priority?: TrailPriority
  type?: TrailType
  /** @deprecated - Only present on old trails created before native reviews */
  github_pr_number?: number | null
  /** Reviewer summary, updated when reviews are submitted */
  reviewers?: TrailReviewer[]
  /** SHA of the merge-base commit at the time the trail was merged (divergence point from base) */
  merge_base_sha?: string | null
  /** SHA of the trail branch HEAD at the time it was merged */
  head_sha?: string | null
}

/** Reply to a trail comment */
export interface TrailCommentReply {
  id: string
  author: string
  created_at: string
  body: string
}

/** Trail comment with threading support */
export interface TrailComment {
  id: string
  author: string
  created_at: string
  body: string
  resolved: boolean
  resolved_by: string | null
  resolved_at: string | null
  replies: TrailCommentReply[]
}

/** Discussion file format for trails */
export interface TrailDiscussion {
  comments: TrailComment[]
}

/** Reference to a checkpoint associated with a trail */
export interface TrailCheckpointRef {
  checkpoint_id: string
  commit_sha: string
  created_at: string
  summary: string | null
}

/** Checkpoints file format for trails - links checkpoints to this trail */
export interface TrailCheckpoints {
  /** Checkpoint references, ordered by creation time (newest first) */
  checkpoints: TrailCheckpointRef[]
}

/** Full trail data (metadata + discussion + checkpoints + reviews) as stored in git */
export interface Trail {
  metadata: TrailMetadata
  discussion: TrailDiscussion
  checkpoints: TrailCheckpoints
  reviews: TrailReviews
}

/** Trail info for API responses (includes computed fields) */
export interface TrailInfo {
  trail_id: string
  branch: string
  base: string
  title: string
  body: string
  status: TrailStatus
  author: string
  assignees: string[]
  labels: string[]
  created_at: string
  updated_at: string
  merged_at: string | null
  priority: TrailPriority
  type: TrailType | null
  reviewers: TrailReviewer[]
  // Computed from discussion
  comment_count: number
  unresolved_count: number
  // Computed from checkpoints (via branch match)
  checkpoint_count: number
  // Commits ahead of base branch (from GitHub compare API)
  commits_ahead?: number
  // Trail evaluation scores (from latest completed trail-eval runs)
  confidence?: number
  risk?: number
  drift?: number
}

